// Cyrus behaviour oracle (oracle-1): the owner-facing "What we verified" panel. Pure + client-safe.
// Plain words only (no RCON, no bot, no expectation ids): what the mod should do, and whether a real test server showed it.
import type { StoredFunctional } from "./types";
import { readFunctional } from "./evaluate";

export type VerifiedRow = { text: string; tone: "ok" | "bad" | "none"; word: string; why: string | null };
export type VerifiedPanel = { headline: string; tone: "ok" | "bad" | "warn" | "none"; rows: VerifiedRow[]; foot: string } | null;

const WORD = { pass: "worked", fail: "did not work", not_run: "not tried", not_testable: "not testable yet" } as const;
const TONE = { pass: "ok", fail: "bad", not_run: "none", not_testable: "none" } as const;

/** Soften internal wording for the owner (the stored reason is for admins and the eval). */
function plainWhy(s: string | null): string | null {
  if (!s) return null;
  return s
    .replace(/^not flown: /, "")
    .replace(/the flight's time cap/, "the test's time limit was reached")
    .replace(/the flight's scenario limit was reached/, "the test's size limit was reached")
    .replace(/console check/g, "server command")
    .replace(/oracle error: .*/, "our checker had a problem (this does not count against your mod)")
    .slice(0, 200);
}

/** The panel for one build's stored Test Flight (null when no behaviour record exists). Failed first, then worked. */
export function verifiedPanel(testFlight: unknown): VerifiedPanel {
  const f = readFunctional((testFlight as { functional?: unknown } | null)?.functional);
  if (!f) return null;
  const order = { fail: 0, pass: 1, not_run: 2, not_testable: 3 } as const;
  const rows = [...f.expectations].sort((a, b) => order[a.status] - order[b.status] || Number(a.id.slice(1)) - Number(b.id.slice(1))).slice(0, 24)
    .map((e) => ({ text: e.title, tone: TONE[e.status], word: WORD[e.status], why: e.status === "pass" ? null : plainWhy(e.reason) } as VerifiedRow));
  const { passed, failed, total } = f.counts;
  const headline = f.verdict === "not_run" ? "Behaviour not tested yet"
    : failed ? `${failed} of ${passed + failed} things we tried did not work`
    : `${passed} of ${passed + failed} things we tried worked`;
  const tone: NonNullable<VerifiedPanel>["tone"] = f.verdict === "failed" ? "bad" : f.verdict === "passed" ? (passed + failed < total ? "warn" : "ok") : "none";
  const foot = f.verdict === "not_run"
    ? (f.reason ? `Not tested: ${plainWhy(f.reason)}.` : "No check could run on the test server.")
    : "A test player tried these on a real Minecraft server with only your mod installed. It does not cover everything a mod can do, and visuals (textures, models) need a real game client.";
  return { headline, tone, rows, foot };
}

/** One short line for lists and the mod page. */
export function verifiedLine(f: StoredFunctional | null): string | null {
  if (!f) return null;
  return f.label;
}
