import { useEffect, useMemo, useRef, useState } from "react";
import { CyrusAvatar } from "@/components/cyrus/brand/CyrusBrand";
import { EditIcon } from "@/components/cyrus/icons/ui";
import { GAME_BY_ID, engineMeta } from "@/lib/cyrus/data";
import { getGame } from "@/lib/cyrus/store";
import { buildModNotes } from "@/lib/cyrus/engine";
import { useModNotes, useStore } from "@/lib/cyrus/store";
import type { Mod, ModVersion } from "@/lib/cyrus/types";
import { Markdown } from "./Markdown";

export function NotesTab({ mod, version }: { mod: Mod; version?: ModVersion }) {
  const { mine: stored, cyrus: aiNotes } = useModNotes(mod.id);
  const setNote = useStore((s) => s.setNote);
  const [draft, setDraft] = useState(stored);
  const [saved, setSaved] = useState<"idle" | "saving" | "saved">("idle");
  const timer = useRef(0);

  useEffect(() => {
    setDraft(stored);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [mod.id]);

  const cyrusNotes = useMemo(() => {
    if (aiNotes) return aiNotes;
    return buildModNotes({
      game: getGame(mod.gameId) ?? GAME_BY_ID.minecraft,
      category: engineMeta(mod.category, `${mod.name} ${mod.summary}`),
      modName: mod.name,
      prompt: `${mod.name}: ${mod.summary}`,
      model: version?.model ?? "katara",
      version: Number(version?.label.slice(1) ?? 1),
    });
  }, [aiNotes, mod, version]);

  const onChange = (v: string) => {
    setDraft(v);
    setSaved("saving");
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => {
      setNote(mod.id, v);
      setSaved("saved");
    }, 450);
  };

  return (
    <div className="min-h-0 flex-1 space-y-4 overflow-y-auto px-4 py-4">
      <section className="rounded-xl border border-cy-line bg-[rgb(var(--glow)/0.04)]">
        <header className="flex items-center gap-2 border-b border-cy-line px-4 py-2.5">
          <EditIcon className="text-cy-accent" />
          <h3 className="font-cy-display text-[13px] font-semibold text-cy-ink">Your notes</h3>
          <span className="ml-auto text-[10.5px] text-cy-faint">
            {saved === "saving" ? "Saving…" : saved === "saved" ? (mod.real ? "Saved" : "Saved on this device") : `${draft.length} chars`}
          </span>
        </header>
        <textarea
          value={draft}
          onChange={(e) => onChange(e.target.value)}
          placeholder="Ideas, balance tweaks, bugs to fix in the next version…"
          className="block min-h-[120px] w-full resize-y bg-transparent px-4 py-3 text-[13px] leading-relaxed text-cy-ink outline-none placeholder:text-cy-faint"
        />
      </section>

      <section className="rounded-xl border border-cy-line">
        <header className="flex items-center gap-2 border-b border-cy-line px-4 py-2.5">
          <CyrusAvatar size={20} />
          <h3 className="font-cy-display text-[13px] font-semibold text-cy-ink">Cyrus notes</h3>
          <span className="ml-auto text-[10.5px] text-cy-faint">{version ? `for ${version.label}` : "draft"}</span>
        </header>
        <div className="px-4 py-3">
          <Markdown source={cyrusNotes} />
        </div>
      </section>
    </div>
  );
}

